const fs = require('fs');
const http = require('http');

// Read and parse .env.test
const envContent = fs.readFileSync('.env.test', 'utf8');
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
});

console.log('Parsed environment variables:', JSON.stringify(envVars, null, 2));

// Create JSON data
const postData = JSON.stringify(envVars);

// Try to make the POST request
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

console.log('\\nAttempting to POST to', options.hostname + ':' + options.port + options.path);

const req = http.request(options, (res) => {
  console.log('Response status:', res.statusCode);
  console.log('Response headers:', JSON.stringify(res.headers));

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response body:', responseData);
  });
});

req.on('error', (e) => {
  console.error('Request failed:', e.message);
});

req.write(postData);
req.end();
"

